        for expression in expressions(&module.functions[1]) {
            match &expression.kind {
                ExprKind::Builtin(Builtin::ListGet, _) => {
                    reads += 1;
                    assert_eq!(facts.integer(expression), None);
                }
                ExprKind::Builtin(Builtin::Print, args) => {
                    assert_eq!(
